GREEN, YELLOW, RED = 17, 27, 22

GPIO.setmode(GPIO.BCM)
GPIO.setup(23, GPIO.OUT, initial=GPIO.LOW)                 # TRIG
GPIO.setup(24, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)        # ECHO
GPIO.setup(17, GPIO.OUT, initial=GPIO.LOW)                 # green LED
GPIO.setup(27, GPIO.OUT, initial=GPIO.LOW)                 # yellow LED
GPIO.setup(22, GPIO.OUT, initial=GPIO.LOW)                 # red LED
GPIO.setup(18, GPIO.OUT, initial=GPIO.LOW)                 # buzzer transistor
tone = GPIO.PWM(18, 2000)    # 2 kHz beep


def distance_cm():
    GPIO.output(TRIG, GPIO.HIGH)
    time.sleep(0.00001)          # 10 us trigger pulse
    GPIO.output(TRIG, GPIO.LOW)
    t0 = time.time()
    while GPIO.input(ECHO) == 0:
        if time.time() - t0 > 0.03:
            return None
    start = time.time()
    while GPIO.input(ECHO) == 1:
        if time.time() - start > 0.03:
            return None
    return (time.time() - start) * 34300 / 2


def show(g, y, r):
    GPIO.output(GREEN, g)
    GPIO.output(YELLOW, y)
    GPIO.output(RED, r)


try:
    beep_on = False
    last_toggle = time.time()
    while True:
        d = distance_cm()
        if d is None or d > 100:
            show(1, 0, 0); period = None      # far: green, silent
        elif d > 50:
            show(1, 0, 0); period = 0.6       # green, slow beeps
        elif d > 20:
            show(0, 1, 0); period = 0.25      # yellow, fast beeps
        else:
            show(0, 0, 1); period = 0         # red, solid tone
        print("distance:", "--" if d is None else round(d, 1), "cm")

        if period is None:
            if beep_on:
                tone.stop(); beep_on = False
        elif period == 0:
            if not beep_on:
                tone.start(50); beep_on = True
        elif time.time() - last_toggle >= period:
            if beep_on:
                tone.stop()
            else:
                tone.start(50)
            beep_on = not beep_on
            last_toggle = time.time()
        time.sleep(0.06)
except KeyboardInterrupt:
    pass
finally:
    tone.stop()
    GPIO.cleanup()
